#nullable enable // autogenerated

using System.Collections.Generic;
using MVZ2Logic.UI;
using UnityEngine;

namespace MVZ2Logic.Models.Components
{
    /// <summary>
    /// 根据实体模型布尔属性切换整套皮肤：originalSprites 与 releasedSprites 按索引成对，
    /// 属性为真时把渲染器上的原皮肤替换为对应解放皮肤，为假时还原。
    /// </summary>
    public class TrueNameReleaseSpriteSetter : ModelComponent
    {
        public override void UpdateFrame(float deltaTime)
        {
            if (Model == null)
                return;
            var released = Model.GetProperty<bool>(propertyName);
            if (!released && !beforeReleased)
                return;
            beforeReleased = released;

            var originals = originalSprites;
            var releases = releasedSprites;
            if (originals == null || releases == null)
                return;
            var count = Mathf.Min(originals.Length, releases.Length);

            var resolvers = Model.transform.GetComponentsInChildren<SpriteRendererResolver>(true);
            foreach (var resolver in resolvers)
            {
                var current = resolver.BaseSprite;
                if (current == null)
                    continue;
                for (int i = 0; i < count; i++)
                {
                    if (released)
                    {
                        if (current == originals[i])
                        {
                            resolver.SetSprite(releases[i]);
                        }
                    }
                    else
                    {
                        if (current == releases[i])
                        {
                            resolver.SetSprite(originals[i]);
                        }
                    }
                }
            }
        }
        [SerializeField]
        private string propertyName = "TrueNameReleased";
        public Sprite[]? originalSprites;
        public Sprite[]? releasedSprites;
        private bool beforeReleased;
    }
}

